def tictactoe_winner(moves):
    board = [[''] * 3 for _ in range(3)]
    for i, (r, c) in enumerate(moves):
        board[r][c] = 'X' if i % 2 == 0 else 'O'
    lines = [[(r, c) for c in range(3)] for r in range(3)] + [[(r, c) for r in range(3)] for c in range(3)] + [[(i, i) for i in range(3)], [(i, 2 - i) for i in range(3)]]
    for line in lines:
        vals = {board[r][c] for r, c in line}
        if len(vals) == 1 and '' not in vals:
            return vals.pop()
    return 'Draw' if len(moves) == 9 else 'Pending'
